<?php require 'functions.php';require_admin();if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$q=$conn->prepare('DELETE FROM items WHERE id=?');$q->bind_param('i',$id);$q->execute();flash('success','Listing removed.');redirect('admin.php');}$counts=[];foreach(['users','items','claims'] as $t)$counts[$t]=$conn->query("SELECT COUNT(*) n FROM $t")->fetch_assoc()['n'];$items=$conn->query('SELECT i.*,u.name FROM items i JOIN users u ON u.id=i.user_id ORDER BY i.created_at DESC');$page_title='Admin dashboard';require 'header.php'; ?>
<div class="mb-4"><p class="text-primary fw-semibold mb-1">ADMINISTRATION</p><h1 class="h2 fw-bold mb-0">Dashboard</h1></div><div class="row g-3 mb-4"><?php foreach(['users'=>'Members','items'=>'Listings','claims'=>'Claims'] as $key=>$label):?><div class="col-md-4"><div class="stat p-4"><div class="text-secondary small text-uppercase"><?=$label?></div><div class="display-6 fw-bold"><?=$counts[$key]?></div></div></div><?php endforeach;?></div><div class="card"><div class="card-header bg-white py-3 fw-bold">All listings</div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th class="ps-4">Item</th><th>Posted by</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php while($item=$items->fetch_assoc()):?><tr><td class="ps-4"><a class="text-decoration-none fw-semibold" href="item.php?id=<?=$item['id']?>"><?=e($item['title'])?></a><div class="small text-secondary"><?=e($item['location'])?></div></td><td><?=e($item['name'])?></td><td><span class="badge badge-<?=e($item['status'])?> text-capitalize"><?=e($item['status'])?></span></td><td><?=date('M j',strtotime($item['created_at']))?></td><td class="text-end pe-4"><a class="btn btn-sm btn-outline-danger" onclick="return confirm('Remove this listing?')" href="admin.php?delete=<?=$item['id']?>">Remove</a></td></tr><?php endwhile;?></tbody></table></div></div><?php require 'footer.php'; ?>
